grM(){return"\u064a\u064f\u0628\u0642\u064a \u0627\u0644\u0644\u0648\u062d\u0629 \u0636\u0645\u0646 \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0648\u0627\u0642\u0639\u0629 \u0625\u0644\u0649 \u064a\u0645\u064a\u0646 \u0646\u0642\u0637\u0629 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0623\u0633\u0641\u0644\u0647\u0627."},
gol(){return"\u0641\u062a\u062d Butterfly \u0641\u064a \u0648\u0636\u0639 \u0645\u0644\u0621 \u0627\u0644\u0634\u0627\u0634\u0629 \u0625\u0630\u0627 \u0623\u0645\u0643\u0646."},
gqk(){return"\u064a\u063a\u064a\u0631 \u0646\u0645\u0637 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0645\u0633\u062a\u0642\u0644\u064b\u0627 \u0639\u0646 \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0641\u0627\u062a\u062d \u0623\u0648 \u0627\u0644\u062f\u0627\u0643\u0646 \u0627\u0644\u0645\u062d\u062f\u062f."},
gug(){return"\u0627\u0633\u062a\u062e\u062f\u0645 \u062a\u062e\u0637\u064a\u0637 \u0633\u0637\u062d \u0627\u0644\u0645\u0643\u062a\u0628 \u0623\u0648 \u0627\u0644\u062c\u0648\u0627\u0644 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u0644\u062c\u0647\u0627\u0632\u0643."},
gqg(){return"\u064a\u063a\u064a\u0631 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0648\u062d\u062c\u0645 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0648\u0627\u062c\u0647\u0629. \u0644\u0627 \u064a\u063a\u064a\u0631 \u062d\u062c\u0645 \u0645\u062d\u062a\u0648\u0649 \u0645\u0644\u0627\u062d\u0638\u062a\u0643."},
gr9(){return"\u064a\u0633\u062a\u062e\u062f\u0645 \u062a\u0628\u0627\u064a\u0646\u0627\u062a \u0644\u0648\u0646\u064a\u0629 \u0623\u0643\u062b\u0631 \u0648\u0636\u0648\u062d\u064b\u0627 \u0644\u064a\u0633\u0647\u0644 \u062a\u0645\u064a\u064a\u0632 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u062d\u0643\u0645 \u0648\u0627\u0644\u0646\u0635\u0648\u0635."},
gt4(){return"\u064a\u0633\u062a\u062e\u062f\u0645 \u0634\u0631\u064a\u0637 \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0646\u0638\u0627\u0645 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u062e\u0627\u0635 \u0628\u0640 Butterfly."},
gun(){return"\u064a\u062d\u062f\u062f \u0645\u0643\u0627\u0646 \u0644\u0648\u062d\u0629 \u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0623\u062f\u0627\u0629 \u0623\u0648 \u0627\u0644\u0639\u0646\u0635\u0631 \u0627\u0644\u0645\u062d\u062f\u062f."},
gt6(){return"\u064a\u0639\u0631\u0636 \u0634\u0631\u064a\u0637 \u062a\u0646\u0642\u0644 \u062f\u0627\u0626\u0645 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0648\u0627\u0633\u0639\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0633\u0631\u064a\u0639 \u0625\u0644\u0649 \u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a."},
gtw(){return"\u064a\u062d\u062f\u062f \u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u062e\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0623\u062f\u0627\u0629 \u062a\u0638\u0647\u0631 \u0623\u0639\u0644\u0649 \u0623\u0648 \u0623\u0633\u0641\u0644 \u0627\u0644\u0644\u0648\u062d\u0629."},
go7(){return"\u064a\u062d\u062f\u062f \u0645\u062a\u0649 \u064a\u0638\u0647\u0631 \u0634\u0631\u064a\u0637 \u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0627\u0644\u0623\u0635\u063a\u0631 \u062d\u062c\u0645\u064b\u0627 \u0648\u0627\u0644\u0645\u0628\u0633\u0637 \u0623\u062b\u0646\u0627\u0621 \u062a\u062d\u0631\u064a\u0631 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629."},
gtH(){return'\u064a\u0645\u0646\u0639 \u0638\u0647\u0648\u0631 \u0639\u0644\u0627\u0645\u0627\u062a \u063a\u064a\u0631 \u0645\u0642\u0635\u0648\u062f\u0629 \u0646\u0627\u062a\u062c\u0629 \u0639\u0646 \u064a\u062f\u0643 \u0623\u0648 \u0627\u0644\u0641\u0623\u0631\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u062a\u062d\u062f\u064a\u062f \u0645\u062a\u0649 \u064a\u0645\u0651\u0643\u0646 \u0648\u0636\u0639 "\u0627\u0644\u0642\u0644\u0645 \u0641\u0642\u0637".'},
go1(){return"\u064a\u0639\u0631\u0636 \u062a\u0628\u062f\u064a\u0644\u0627\u064b \u0633\u0631\u064a\u0639\u0627\u064b \u0625\u0644\u0649 \u0648\u0636\u0639  \u201d\u0627\u0644\u0642\u0644\u0645 \u0641\u0642\u0637\u201c \u0641\u064a \u0627\u0644\u0645\u062d\u0631\u0631 \u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u062a\u0634\u0641 Butterfly \u0648\u062c\u0648\u062f \u0642\u0644\u0645."},
grj(){return"\u064a\u062d\u062f\u062f \u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0644\u0636\u063a\u0637 \u0627\u0644\u0642\u0644\u0645 \u062a\u0623\u062b\u064a\u0631 \u0639\u0644\u0649 \u0634\u0643\u0644 \u0627\u0644\u062e\u0637\u060c \u0643\u0645\u0627 \u064a\u0642\u0644\u0644 \u0645\u0646 \u062a\u0623\u062b\u064a\u0631 \u0642\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u063a\u064a\u0631 \u0627\u0644\u062f\u0642\u064a\u0642\u0629 \u0627\u0644\u062a\u064a \u062a\u0646\u062a\u062c \u0645\u0646 \u0628\u0639\u0636 \u0627\u0644\u0623\u0642\u0644\u0627\u0645."},
gt_(){return"\u064a\u062a\u064a\u062d \u0644\u0625\u064a\u0645\u0627\u0621\u0627\u062a \u0627\u0644\u0644\u0645\u0633 \u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u0644\u0648\u062d\u0629 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0645\u0639 \u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629."},
goe(){return"\u064a\u0642\u0648\u0645 \u0628\u062a\u0642\u0633\u064a\u0645 \u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u064a\u0631\u0627\u062f \u0627\u0644\u0645\u0643\u0648\u0646\u0629 \u0645\u0646 \u0639\u062f\u0629 \u0635\u0641\u062d\u0627\u062a \u0625\u0644\u0649 \u0635\u0641\u062d\u0627\u062a \u0645\u0646\u0641\u0635\u0644\u0629 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0648\u0636\u0639 \u0643\u0644 \u0634\u064a\u0621 \u0641\u064a \u0635\u0641\u062d\u0629 \u0648\u0627\u062d\u062f\u0629."},
